insert into public.workshop_events (slug,title,description,date,starts_at,ends_at,venue,city,type,relationship,image,source_url,registration_url,participant_url,registration_deadline,registration_status,lifecycle,partners,featured,published,verified_at) values ('hacktoberfest-hack-day-2026','Hacktoberfest Hack Day','A day for open-source AI, fresh ideas and building together. Join the shortlisted builders at Startup Park for hands-on hacking, project demos and a room full of people who love making things. Teams of one to three. Bring your laptop, charger and ID. Registration closed on 7 October; confirmed participants should check the official event page and participant group for instructions.','2026-10-18','2026-10-18T08:30:00+05:30','2026-10-18T18:30:00+05:30','Startup Park','Bengaluru','hackathon','hosted','/events/hacktoberfest-2026.webp','https://events.mlh.com/events/15112-hacktoberfest-hack-day-bengaluru-krowdkraft','https://events.mlh.com/events/15112-hacktoberfest-hack-day-bengaluru-krowdkraft','https://chat.whatsapp.com/FXmyMCczXwFIqxySjp2OTl','2026-10-07','closed','scheduled','["Major League Hacking","DEV","DigitalOcean","Startup Park","ShipWright","Where U Elevate"]',true,true,'2026-10-14T18:00:00Z') on conflict (slug) do nothing;
