insert into public.workshop_articles (slug,title,subtitle,description,date,topic,author,href,image,feed_guid,published) values ('medium-91262836da0c','How to Get Cursor Pro for Free Through MLH Global Hack Week (Worth $20/Month)','','Here is how I claimed the Cursor Pro promotional offer through MLH Global Hack Week, from registration to redeeming the code.','2026-10-14','From Medium','Darshan Krishna N','https://medium.com/@cryptech_dk/how-to-get-cursor-pro-for-free-through-mlh-global-hack-week-worth-20-month-91262836da0c','https://cdn-images-1.medium.com/max/1024/1*ZhYhZF7Z3TxCTvpQsEEMUw.png','https://medium.com/p/91262836da0c',true) on conflict (slug) do nothing;
insert into public.workshop_articles (slug,title,subtitle,description,date,topic,author,href,image,feed_guid,published) values ('medium-5b94af688c0b','Are Online Certifications Worth It? Here’s What Every Student Should Know','','With the rise of free and paid online learning platforms, it’s now easier than ever to sign up for a course and get a certificate. But here’s what’s actually happening:Many students are doing courses from random websites that are not well recognized and that can hurt more than help.','2025-05-14','From Medium','Darshan Krishna N','https://medium.com/@cryptech_dk/are-online-certifications-worth-it-heres-what-every-student-should-know-5b94af688c0b','https://cdn-images-1.medium.com/max/650/1*UeRHHsfOhHSygdZeoZ3S9g.png','https://medium.com/p/5b94af688c0b',true) on conflict (slug) do nothing;
insert into public.workshop_articles (slug,title,subtitle,description,date,topic,author,href,image,feed_guid,published) values ('medium-741d900a4e97','Dev vs DSA: Understanding the Balance, Not the Battle','','Every few weeks, a post goes viral on LinkedIn or Twitter:','2025-05-06','From Medium','Darshan Krishna N','https://medium.com/@cryptech_dk/dev-vs-dsa-understanding-the-balance-not-the-battle-741d900a4e97','https://cdn-images-1.medium.com/max/1024/1*36GE18TXqRIGbnCnhSPWPQ.png','https://medium.com/p/741d900a4e97',true) on conflict (slug) do nothing;
insert into public.workshop_articles (slug,title,subtitle,description,date,topic,author,href,image,feed_guid,published) values ('medium-ff7c83cef26c','Hidden Gems for Internships and Jobs: Underrated Platforms You Shouldn’t Ignore','','When it comes to hunting for internships and jobs, platforms like LinkedIn, Naukri, and Internshala often come to mind first. However, while these platforms offer a massive range of opportunities, they are also incredibly saturated. With thousands (or even lakhs) of applicants applying for the same roles, standing out becomes a real challenge.','2025-04-27','From Medium','Darshan Krishna N','https://medium.com/@cryptech_dk/hidden-gems-for-internships-and-jobs-underrated-platforms-you-shouldnt-ignore-ff7c83cef26c','https://cdn-images-1.medium.com/max/1024/1*KRZRxTDiF1t2qXms9gO-JQ.jpeg','https://medium.com/p/ff7c83cef26c',true) on conflict (slug) do nothing;
